function addLights(scene) {
  const lights = new THREE.Group();
  lights.add(new THREE.HemisphereLight(0xffffff, 0x60656e, 2.0));
  const sun = new THREE.DirectionalLight(0xffffff, 1.6);
  sun.position.set(3, 6, 4);
